CREATE TABLE public.conc_bank_receipt_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hotel_id text NOT NULL REFERENCES public.hotels(id),provider text NOT NULL DEFAULT 'rede' CHECK(provider='rede'),prefix text NOT NULL CHECK(length(btrim(prefix))>=12),enabled boolean NOT NULL DEFAULT true,updated_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hotel_id,provider,prefix));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.conc_bank_receipt_rules TO authenticated;
GRANT ALL ON public.conc_bank_receipt_rules TO service_role;
ALTER TABLE public.conc_bank_receipt_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_rules_access ON public.conc_bank_receipt_rules TO authenticated USING(public.can_access_conciliacao(auth.uid()) AND public.can_view_hotel_data(auth.uid(),hotel_id)) WITH CHECK(public.can_access_conciliacao(auth.uid()) AND public.can_view_hotel_data(auth.uid(),hotel_id) AND updated_by=auth.uid());
CREATE FUNCTION public.conc_is_rede_bank(p_hotel text,p_description text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT starts_with(upper(btrim(coalesce(p_description,''))),'RECEBIMENTO REDE') OR EXISTS(SELECT 1 FROM public.conc_bank_receipt_rules WHERE hotel_id=p_hotel AND enabled AND starts_with(upper(btrim(coalesce(p_description,''))),upper(btrim(prefix)))); $$;
REVOKE ALL ON FUNCTION public.conc_is_rede_bank(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conc_is_rede_bank(text,text) TO authenticated,service_role,supabase_read_only_user;
CREATE TABLE public.conc_rede_deduction_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hotel_id text NOT NULL REFERENCES public.hotels(id),receipt_id uuid NOT NULL REFERENCES public.conc_rede_recebidos(id),component_id uuid NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('ajuste','chargeback')),amount numeric NOT NULL CHECK(amount>0),note text NOT NULL CHECK(length(btrim(note))>=10),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conc_rede_deduction_links TO authenticated;
GRANT ALL ON public.conc_rede_deduction_links TO service_role;
ALTER TABLE public.conc_rede_deduction_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY deduction_links_read ON public.conc_rede_deduction_links FOR SELECT TO authenticated USING(public.can_access_conciliacao(auth.uid()) AND public.can_view_hotel_data(auth.uid(),hotel_id));
CREATE FUNCTION public.conc_rede_deduction_allocation(p_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
WITH target AS (SELECT * FROM public.conc_rede_recebidos WHERE id=p_id), deductions AS (
SELECT c.id,'chargeback'::text kind,c.data_debito dt,nullif(upper(public.unaccent_safe(btrim(c.bandeira))),'') brand,c.valor_descontado amount,concat_ws(' · ',c.tipo,c.motivo_cancelamento) label,c.nsu_cv nsu FROM public.conc_rede_chargebacks c JOIN target t ON t.hotel_id=c.hotel_id AND t.data=c.data_debito
UNION ALL SELECT a.id,'ajuste',a.data_ajuste,nullif(upper(public.unaccent_safe(btrim(a.bandeira))),''),a.valor_cobrado,a.motivo,NULL FROM public.conc_rede_ajustes a JOIN target t ON t.hotel_id=a.hotel_id AND t.data=a.data_ajuste WHERE NOT (upper(public.unaccent_safe(a.motivo)) ~ '(CANCELAMENTO|CONTESTA)' AND round((SELECT sum(x.valor_cobrado) FROM public.conc_rede_ajustes x WHERE x.hotel_id=a.hotel_id AND x.data_ajuste=a.data_ajuste AND upper(public.unaccent_safe(x.motivo)) ~ '(CANCELAMENTO|CONTESTA)'),2)=round((SELECT sum(c.valor_descontado) FROM public.conc_rede_chargebacks c WHERE c.hotel_id=a.hotel_id AND c.data_debito=a.data_ajuste),2))
), candidates AS (SELECT d.* FROM deductions d CROSS JOIN target t WHERE (d.brand IS NULL OR d.brand=upper(public.unaccent_safe(btrim(t.bandeira)))) AND d.amount>0),linked AS (SELECT c.*,l.note FROM candidates c JOIN public.conc_rede_deduction_links l ON l.component_id=c.id AND l.kind=c.kind AND l.receipt_id=p_id AND round(l.amount,2)=round(c.amount,2))
SELECT jsonb_build_object('deductions',coalesce((SELECT jsonb_agg(to_jsonb(l)) FROM linked l),'[]'::jsonb),'deduction_total',coalesce((SELECT sum(amount) FROM linked),0),'candidates',coalesce((SELECT jsonb_agg(to_jsonb(c)||jsonb_build_object('allocated',EXISTS(SELECT 1 FROM public.conc_rede_deduction_links l WHERE l.component_id=c.id))) FROM candidates c),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.conc_rede_deduction_allocation(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.conc_rede_deduction_allocation(uuid) TO service_role,supabase_read_only_user;
CREATE FUNCTION public.conc_allocate_rede_deductions(p_hotel text,p_receipt uuid,p_components uuid[],p_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r record;c jsonb;total numeric:=0;liquid numeric;count_ids int:=0; BEGIN
IF auth.uid() IS NULL OR NOT public.can_access_conciliacao(auth.uid()) OR NOT public.can_view_hotel_data(auth.uid(),p_hotel) THEN RAISE EXCEPTION 'Sem permissão'; END IF;
IF length(btrim(coalesce(p_note,'')))<10 OR coalesce(cardinality(p_components),0)=0 THEN RAISE EXCEPTION 'Selecione descontos e justifique a composição'; END IF;
PERFORM pg_advisory_xact_lock(hashtext('settlement:'||p_hotel));
SELECT * INTO r FROM public.conc_rede_recebidos WHERE id=p_receipt AND hotel_id=p_hotel AND matched_bank_id IS NULL FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Recebimento indisponível'; END IF;
IF (SELECT count(*) FROM public.conc_rede_recebidos x WHERE x.hotel_id=r.hotel_id AND x.data=r.data AND upper(public.unaccent_safe(x.bandeira))=upper(public.unaccent_safe(r.bandeira)) AND upper(public.unaccent_safe(x.modalidade))=upper(public.unaccent_safe(r.modalidade)))<>1 THEN RAISE EXCEPTION 'Lotes repetidos exigem composição individual comprovada'; END IF;
FOR c IN SELECT value FROM jsonb_array_elements(public.conc_rede_deduction_allocation(p_receipt)->'candidates') WHERE (value->>'id')::uuid=ANY(p_components) LOOP IF (c->>'allocated')::boolean THEN RAISE EXCEPTION 'Desconto já utilizado'; END IF; total:=total+(c->>'amount')::numeric;count_ids:=count_ids+1; END LOOP;
IF count_ids<>cardinality(p_components) THEN RAISE EXCEPTION 'Desconto inválido ou repetido'; END IF;
SELECT sum(net) INTO liquid FROM public.conc_batch_rows('rede',p_receipt);
IF liquid IS NULL OR round(liquid-total-coalesce((public.conc_rede_deduction_allocation(p_receipt)->>'deduction_total')::numeric,0),2)<>round(r.valor_depositado,2) THEN RAISE EXCEPTION 'A composição não fecha com o recebido'; END IF;
INSERT INTO public.conc_rede_deduction_links(hotel_id,receipt_id,component_id,kind,amount,note,created_by) SELECT p_hotel,p_receipt,(value->>'id')::uuid,value->>'kind',(value->>'amount')::numeric,btrim(p_note),auth.uid() FROM jsonb_array_elements(public.conc_rede_deduction_allocation(p_receipt)->'candidates') WHERE (value->>'id')::uuid=ANY(p_components);
END $$;
REVOKE ALL ON FUNCTION public.conc_allocate_rede_deductions(text,uuid,uuid[],text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.conc_allocate_rede_deductions(text,uuid,uuid[],text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.conc_batch_summary(p_source text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r record;n int;ok int;liquid numeric;missing int;target numeric;twins boolean:=false;adj jsonb:='{}';deductions numeric:=0;composed numeric;sums_ok boolean; BEGIN
IF p_source='rede' THEN SELECT id,hotel_id,data dt,concat_ws(' · ',bandeira,modalidade) label,valor_depositado amount INTO r FROM public.conc_rede_recebidos WHERE id=p_id; IF NOT FOUND THEN RETURN NULL; END IF;
SELECT count(*)>1,sum(x.valor_depositado) INTO twins,target FROM public.conc_rede_recebidos x JOIN public.conc_rede_recebidos y ON y.id=p_id WHERE x.hotel_id=y.hotel_id AND x.data=y.data AND upper(public.unaccent_safe(btrim(x.bandeira)))=upper(public.unaccent_safe(btrim(y.bandeira))) AND upper(public.unaccent_safe(btrim(x.modalidade)))=upper(public.unaccent_safe(btrim(y.modalidade)));
adj:=public.conc_rede_deduction_allocation(p_id);deductions:=coalesce((adj->>'deduction_total')::numeric,0);
ELSIF p_source='b2b' THEN SELECT id,hotel_id,data_operacao dt,descricao label,abs(valor_recebivel_liquido) amount INTO r FROM public.conc_b2b_receipts WHERE id=p_id AND tipo_lancamento='deposit';IF NOT FOUND THEN RETURN NULL;END IF;target:=r.amount;ELSE RETURN NULL;END IF;
SELECT count(*),count(*) FILTER(WHERE status='Conciliado'),sum(net),count(*) FILTER(WHERE net IS NULL) INTO n,ok,liquid,missing FROM public.conc_batch_rows(p_source,p_id);
composed:=liquid-deductions;sums_ok:=round(composed,2)=round(target,2);
RETURN jsonb_build_object('source',p_source,'id',r.id,'label',r.label,'date',r.dt,'amount',r.amount,'group_amount',target,'twins',twins,'total',n,'reconciled',ok,'net',liquid,'deduction_total',deductions,'settlement_net',composed,'difference',composed-target,'deductions',coalesce(adj->'deductions','[]'::jsonb),'deduction_candidates',coalesce(adj->'candidates','[]'::jsonb),'complete',NOT twins AND n>0 AND missing=0 AND coalesce(sums_ok,false),'ready',NOT twins AND n>0 AND n=ok AND missing=0 AND coalesce(sums_ok,false),'reason',CASE WHEN twins THEN 'Mais de um lote na mesma data/bandeira/modalidade: faltam parcelas individualizadas; baixa bloqueada' WHEN n=0 THEN 'Relatório de vendas integrantes não encontrado' WHEN missing>0 THEN 'Há parcelas sem valor líquido informado' WHEN NOT coalesce(sums_ok,false) THEN 'Composição líquida divergente: desconto ausente ou sem vínculo inequívoco. Antecipação exige taxa comprovada, sem tolerância presumida.' WHEN n<>ok THEN 'Composição financeira confere, mas há vendas sem conciliação com o Ópera' ELSE 'Composição financeira validada e todas as vendas conciliadas com o Ópera' END);
END $$;
CREATE OR REPLACE FUNCTION public.conc_bank_batches(p_bank uuid) RETURNS TABLE(source text,entry_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ WITH bank AS(SELECT * FROM public.conc_bank_entries WHERE id=p_bank AND (auth.uid() IS NULL OR (public.can_access_conciliacao(auth.uid()) AND public.can_view_hotel_data(auth.uid(),hotel_id))))
SELECT 'rede'::text,r.id FROM bank b JOIN public.conc_rede_recebidos r ON r.hotel_id=b.hotel_id WHERE r.matched_bank_id=b.id OR (b.amount>0 AND public.conc_is_rede_bank(b.hotel_id,b.description) AND r.matched_bank_id IS NULL AND b.line_date BETWEEN r.data-1 AND r.data+3 AND round(b.amount,2)=round(r.valor_depositado,2) AND (NOT starts_with(upper(btrim(b.description)),'RECEBIMENTO REDE') OR (upper(b.description) LIKE '%'||CASE upper(public.unaccent_safe(r.bandeira)) WHEN 'MASTERCARD' THEN 'MAST' WHEN 'AMERICAN EXPRESS' THEN 'AMEX' WHEN 'HIPERCARD' THEN 'HIPER' ELSE upper(public.unaccent_safe(r.bandeira)) END||'%' AND upper(b.description) ~ (' ('||CASE upper(public.unaccent_safe(r.modalidade)) WHEN 'CREDITO' THEN 'CD|AT' WHEN 'DEBITO' THEN 'DB' WHEN 'ANTECIPADO' THEN 'AT' ELSE 'INVALID' END||')[0-9]'))))
UNION ALL SELECT 'b2b',d.id FROM bank b JOIN public.conc_b2b_receipts d ON d.hotel_id=b.hotel_id AND d.tipo_lancamento='deposit' WHERE d.matched_bank_id=b.id OR (b.amount>0 AND b.description ILIKE 'ZOOP%' AND d.matched_bank_id IS NULL AND b.line_date BETWEEN d.data_operacao-5 AND d.data_operacao+10 AND round(b.amount,2)=round(abs(d.valor_recebivel_liquido),2)); $$;
CREATE OR REPLACE FUNCTION public.conc_rede_auto_match(p_hotel text,p_bank_prefix text,p_brand_map jsonb,p_mod_map jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v int:=0;blocked int:=0;r record;b uuid;candidates uuid[];BEGIN
IF auth.uid() IS NULL OR NOT public.can_access_conciliacao(auth.uid()) OR NOT public.can_view_hotel_data(auth.uid(),p_hotel) THEN RAISE EXCEPTION 'Sem permissão';END IF;
PERFORM pg_advisory_xact_lock(hashtext('settlement:'||p_hotel));
FOR r IN SELECT * FROM public.conc_rede_recebidos rr WHERE hotel_id=p_hotel AND matched_bank_id IS NULL AND coalesce(valor_depositado,0)>0 AND NOT EXISTS(SELECT 1 FROM public.conc_settlement_transitions t WHERE t.source='rede' AND t.entry_id=rr.id AND t.undone_at IS NULL) ORDER BY data,id FOR UPDATE LOOP
IF NOT public.conc_batch_ready('rede',r.id) THEN blocked:=blocked+1;CONTINUE;END IF;
SELECT array_agg(be.id) INTO candidates FROM public.conc_bank_entries be WHERE be.hotel_id=p_hotel AND be.matched_at IS NULL AND be.amount>0 AND EXISTS(SELECT 1 FROM public.conc_bank_batches(be.id) c WHERE c.source='rede' AND c.entry_id=r.id) AND (SELECT count(*) FROM public.conc_bank_batches(be.id))=1;
IF cardinality(candidates)=1 THEN b:=candidates[1];PERFORM 1 FROM public.conc_bank_entries WHERE id=b AND matched_at IS NULL FOR UPDATE;IF FOUND THEN UPDATE public.conc_bank_entries SET matched_at=now() WHERE id=b;UPDATE public.conc_rede_recebidos SET matched_bank_id=b,matched_at=now() WHERE id=r.id;v:=v+1;END IF;ELSE blocked:=blocked+1;END IF;
END LOOP;RETURN jsonb_build_object('matched',v,'blocked',blocked);END $$;